#!/usr/bin/env python3
"""Sort a list of [integer_list, integer] elements by multiple criteria."""

from data import data


def sort_key(element):
    """Return a key tuple for sorting.

    Criteria (in order of priority):
    1. Length of the integer list (shorter comes first)
    2. Lexicographic comparison of the integer list
    3. Secondary integer value
    """
    return (len(element[0]), element[0], element[1])


def main():
    sorted_data = sorted(data, key=sort_key)

    output_path = "/app/task_file/output/sorted_result.txt"
    with open(output_path, "w") as f:
        for item in sorted_data:
            f.write(repr(item) + "\n")


if __name__ == "__main__":
    main()
